FRAMES = []   # (section, id, name, note, html, height)
SECTIONS = []

def section(key, title, desc):
    SECTIONS.append((key, title, desc))

def frame(sec, fid, name, note, inner, cls='', h=1080, label=None):
    lab = f'<div class="scr-label">{e(fid)}</div>'
    style = ''
    h = 1080
    FRAMES.append((sec, fid, name, note, f'<div class="fr {cls}"{style}><div class="bg"></div>{inner}{lab}</div>', h))

# ---------------- shared pieces ----------------
LOGO = ('<svg width="190" height="150" viewBox="0 0 38 30" shape-rendering="crispEdges">'
        '<path fill="#7B3FC4" d="M0 4h6l6 10 6-10h2v26h-6V16l-4 7h-2l-4-7v14H0z"/>'
        '<path fill="#E94785" d="M14 0h6l6 10 6-10h6v26h-6V12l-4 7h-2l-4-7v14h-8z" opacity=".95"/></svg>')

def logo(top=110):
    return f'<div class="abs" style="left:865px;top:{top}px">{LOGO}</div>'

def sys_modal(body, w=650, title='симулятор мэра'):
    t = f'<div class="mtab"><span class="h1 px mt">{e(title)}</span><span style="display:inline-flex">{LOGO.replace("width=\"190\" height=\"150\"", "width=\"41\" height=\"32\"")}</span></div>'
    return f'<div class="modal center" style="width:{w}px;margin-top:70px">{t}<div class="mbody"><div class="mcont">{body}</div></div></div>'

def back_head(title):
    return row(btn('назад', 'p', icon='back'), sp(), h3(title, 24), gap=24)

def blk(pressed=None, static=False):
    out = []
    for i, (n, v, c, up, ic) in enumerate(CITY):
        out.append(f'<div class="chipm {"pressed" if pressed == i else ""}">{ico(ic, 40)}<div class="cmt"><span class="cmn">{e(n)}</span>'
                   f'<span class="cmv">{e(v)}</span></div>{badge(c, "pink", "m", "up" if up else "down")}</div>')
    return f'<div class="blk {"static" if static else ""}">' + ''.join(out) + '</div>'

def lpanel(c, mode='active', badge_top=None, tip=False, reception=False):
    tools = []
    for (lab, summ, iid) in c['tools']:
        stt = ''
        if mode in ('wait', 'pause', 'disc', 'p18'):
            stt = 'live' if (mode == 'wait' and lab == 'Совм. инвестиции') else 'dis'
        tools.append(tool(lab, summ, stt))
    sl = []
    for (lab, val, pct, pred) in c['sliders']:
        sst = 'dis' if mode in ('wait', 'pause', 'disc', 'p18', 'obs') else ''
        sl.append(col(h2(lab, 16), slider(val, pct, sst), sm(pred, 12), gap=4))
    head = (badge(badge_top, 'accent', 's') if badge_top else '')
    inner = head + h1(c['title'], 22 if len(c['title']) > 30 else 24, 'ptitle') + budget(c['budget'], c['start'], c['plan'], tip)
    if not reception:
        inner += col(h2('инструменты'), *tools, gap=8) + ''.join(sl)
    return f'<div class="lpan">{panel(inner)}</div>'

def rpanel(c, event=None, more=0, notif=True, extra_notif=None):
    ins = col(h2('входной показатель'), *[inmet(a, b) for a, b in c['inputs']], gap=8)
    k = col(h2('KPI команды'), *[kpirow(*x) for x in c['kpi']], btn('остальные показатели', 'p', cls='btn-sm'), gap=8)
    nts = []
    if extra_notif:
        nts.append(extra_notif)
    if c['notif'] and notif:
        nts.append(f'<div class="notif {"new" if c["id"] == "trn" else ""}">{xbtn()}<span class="nf">{e(c["notif"][0])}</span><span class="ntx">{e(c["notif"][1])}</span></div>')
    if not nts:
        nts.append(sm('Новых уведомлений нет', 13))
    n = col(h2('входящие от комитетов'), *nts[:2], gap=8)
    return f'<div class="rpan">{event_ind(event, more)}{panel(ins + k + n)}</div>'

def ctrl(c, mode='active', cur=None, solo=False, obs=False, reception=False):
    cur = c['i'] if cur is None else cur
    mine = (cur == c['i']) and mode in ('active', 'solo')
    parts = []
    if solo:
        parts.append(btn('завершить игру', 'p'))
        parts.append(roundpill('раунд 03'))
    elif mode == 'p18':
        parts.append(timer('00:42', 'раунд 04'))
    else:
        parts.append(timer('00:12' if mode == 'expiring' else ('01:12' if mode != 'pause' else '00:58'), 'раунд 03', mode == 'expiring'))
    if obs:
        parts += [chip('сводка'), chip('наблюдение', 'pressed')]
    elif not solo:
        parts.append(btn('пауза', 'p', 'dis' if mode in ('pause', 'p18', 'disc', 'reqpause') else '', icon='pause'))
    parts.append(turn(cur, mine=mine or mode == 'expiring', solo=solo))
    if obs:
        parts += [btn('пауза', 'p', icon='pause'), btn('завершить игру', 'p')]
    else:
        parts.append(btn('назад' if reception else 'приёмная', 'p', 'dis' if mode in ('p18', 'disc') else '', icon='back' if reception else None))
        if not reception:
            parts.append(btn('завершить ход', 'a', '' if mode in ('active', 'solo', 'expiring') else 'dis'))
    return '<div class="ctrl">' + ''.join(parts) + '</div>'

def s08(c, mode='active', cur=None, event=None, more=0, top='', solo=False, obs=False, tip=False, extra_notif=None, blkp=None):
    lm = {'expiring': 'active', 'solo': 'active'}.get(mode, mode)
    bt = f'наблюдение · {c["name"]}' if obs else None
    return (blk(blkp) + lpanel(c, 'obs' if obs else lm, bt, tip) + rpanel(c, event, more, extra_notif=extra_notif) +
            ctrl(c, mode, cur, solo, obs) + top)

def f08(sec, fid, name, note, c, **kw):
    frame(sec, fid, name, note, s08(c, **kw))

