def codep(state=''):
    if state == 'error':
        c = code('К7Р2МВ', 'error', 'Комната не найдена. Проверьте код')
    elif state == 'typing':
        c = code('К7Р   ', 'typing')
    else:
        c = code('КОООО Д'.replace(' ', ''), '')
    return col(back_head('введите код комнаты'), c, row(sp(), btn('где его взять?', 'l'), sp()), gap=32)
