COMS = [('комитет по миграции', 0), ('образование, культура и досуг', -380), ('комитет по развитию бизнеса', -700), ('комитет по градостроительству', -140), ('комитет по транспорту', -560), ('комитет по туризму', -735)]
def ccard(n, x, state='', extra=''):
    inner = ''
    if state == 'hover':
        inner = btn('выбрать', 'p', cls='btn-sm cbadge')
    if state in ('pressed', 'choosen'):
        inner = badge('выбран', 'white', 'm', cls='cbadge')
    you = badge('вы', 'pink', 's', cls='you') if state == 'pressed' else ''
    er = '<div class="errtxt">Комитет уже занят</div>' if state == 'error' else ''
    return f'<div class="ccard {state}">{you}<div class="cimg" style="background-position:{x}px -260px">{inner}</div><div class="cn">{e(n)}</div>{er}</div>'
def s04(lock):
    if lock:
        cards = ''.join(ccard(n, x, 'lock') for n, x in COMS)
        top = col(h3('подключились к комнате: 5 из 6', 22), sm('Выбор откроется, когда подключатся все команды', 15), gap=4, ai='center')
    else:
        sts = ['choosen', '', 'hover', 'choosen', 'pressed', 'error']
        cards = ''.join(ccard(n, x, s) for (n, x), s in zip(COMS, sts))
        top = ''
    return col(back_head('выберите комитет'), top, f'<div class="cards">{cards}</div>', btn('далее', 'p', 'dis' if lock else ''), gap=24)
