def tcard(team, com, state, x):
    st_ = {'own': ('не готов', 'white'), 'ownready': ('готов', 'pink'), 'other': ('не готов', 'white'), 'ready': ('готов', 'pink'), 'empty': ('не подключена', 'dark'), 'nc': ('не готов', 'white')}[state]
    inner = ''
    if state == 'own':
        inner = btn('готов!', 'p', cls='btn-sm cbadge')
    you = badge('вы', 'pink', 's', cls='you') if state in ('own', 'ownready') else ''
    nc = f'<span class="abs" style="right:12px;top:12px;z-index:3">{badge("нет связи", "err", "s")}</span>' if state == 'nc' else ''
    cls = 'pressed' if state in ('own', 'ownready') else ('choosen' if state == 'empty' else '')
    return (f'<div class="ccard {cls}">{you}{nc}<div class="cimg" style="height:170px;background-position:{x}px -260px">{inner}</div>'
            f'<div class="cn" style="font-size:20px;min-height:0">{e(team)}</div>{sm(com, 13)}{badge(st_[0], st_[1], "s")}</div>')
def s06(host):
    data = [('Новые горизонты', 'комитет по миграции', 'ready'), ('Знание — сила', 'образование, культура и досуг', 'ready'), ('Бизнес-ангелы', 'комитет по развитию бизнеса', 'nc'),
            ('Ждём команду', 'комитет по градостроительству', 'empty'), ('Транспортники 9Б', 'комитет по транспорту', 'own' if not host else 'ready'), ('Белые ночи', 'комитет по туризму', 'other')]
    cards = ''.join(tcard(t, c, s, x) for (t, c, s), (_, x) in zip(data, COMS))
    codeb = row(h3('код комнаты', 22), sp(), code('К7Р2МВ', show=True), gap=20)
    ctr = col(h3('подключились к комнате: 5 из 6', 20), gap=0, ai='center') if host else ''
    btns = row(btn('начать игру', 'p', 'dis'), btn('отменить игру', 's'), gap=16, jc='center') if host else row(btn('готов', 'p'), btn('изменить', 's'), gap=16, jc='center')
    return col(row(h3('лобби', 24), sp(), gap=0), codeb, ctr, f'<div class="tcards">{cards}</div>', btns, gap=22)
