section('p10', '06 · Поп-апы показателей P-10 (32), P-11 (6), P-12 (8)', 'P-10: название, текущее значение, переменные, график по раундам («Старт» + итог каждого раунда). Для KPI — строки баллов и подпись внизу (4.2.8.12). Рабочие поп-апы без затемнения, перетаскиваются за шапку.')
UNITS = {'₽': ['2,14 трлн ₽', '840,00 млрд ₽', '96,50 млрд ₽', '12,30 млрд ₽', '480 000 ₽'], '%': ['64,2 %', '12,5 %', '98,1 %', '7,5 %', '41,0 %'], 'чел.': ['120 400 чел.', '38 200 чел.', '1 240 000 чел.', '5 410 000 чел.', '640 чел.'],
         '×': ['0,95', '1,10', '0,87', '1,00', '1,32'], 'п.п.': ['+1,2 п.п.', '−0,6 п.п.', '+3,0 п.п.', '−2,1 п.п.', '+0,4 п.п.'], 'ед.': ['124 300 ед.', '86 120 ед.', '2 400 ед.', '310 ед.', '9 870 ед.'],
         'шт.': ['2 шт.', '1 шт.', '4 шт.', '0 шт.', '3 шт.'], 'кв. м': ['1 250 000 кв. м', '320 000 кв. м', '48 000 кв. м', '2 480 000 кв. м', '96 000 кв. м'], 'км': ['4 820 км', '310 км'],
         'авто-экв./сут.': ['640 000 авто-экв./сут.', '480 000 авто-экв./сут.'], '₽/кв. м': ['185 000 ₽/кв. м', '162 000 ₽/кв. м'], 'коэф.': ['1,92', '2,05']}
def sample(u, i):
    v = UNITS.get(u, ['—'])
    return v[i % len(v)]
def chg_for(u, i):
    up = i % 3 != 1
    if u in ('%',):
        return (('+' if up else '−') + ['1,2', '0,4', '3,1'][i % 3] + ' п.п.', up)
    if u in ('п.п.', 'шт.', '×', 'коэф.'):
        return (None, True)
    return (('+' if up else '−') + ['2,1', '0,8', '4,5'][i % 3] + ' %', up)
def p10(title, value, rows_, lines=1, kpi=None, note=None, w=650, seed=1, sub=None):
    rs = []
    for i, (n, u) in enumerate(rows_):
        c, up = chg_for(u, i)
        rs.append(mrow(n, sample(u, i), c, up))
    body = [row(f'<div class="budget" style="flex:1"><span class="px">{e(value.replace("₽", "р."))}</span></div>', gap=0)] + rs
    if kpi:
        green, red, cap = kpi
        body += [mrow('баллы за прошлый раунд', '14 из 25', cls='sub'), mrow('зелёная зона', green, cls='sub'), mrow('красный порог', red, cls='sub')]
    body += [h2('по раундам', 16), graph(w - 56, 220, lines, seed=seed)]
    if note:
        body.append(sm(note, 12))
    if kpi:
        body.append(div('qtip', sm(kpi[2], 14, 'tip-l')))
    body.append(btn('понятно', 'p'))
    return modal(title, col(*body, gap=10), w, sub=sub)
for k, (fid, title, val, rows_, lines, note) in enumerate(P10_CITY):
    h = max(1080, 560 + len(rows_) * 64 + 260)
    frame('p10', fid, title, 'Городской показатель, открывается с любого S-08, S-07, S-09, S-10 по чипу BLK-01. ' + (note or ''), s08(B, blkp=k) + p10(title, val, rows_, lines, note=note, seed=k + 3), h=h)
for k, (fid, cid, short, full, val, rows_, green, red, cap, note) in enumerate(P10_KPI):
    c = CBYID[cid]
    h = max(1080, 760 + len(rows_) * 64 + 260)
    frame('p10', fid, short, f'KPI комитета «{c["name"]}». Полное название: {full}. Значение пересчитывается после хода каждого комитета, точка на графике — только по итогу раунда.' + (' ' + note if note else ''),
          s08(c) + p10(short, val, rows_, kpi=(green, red, cap), note=note, seed=k + 20, sub=full), h=h)
for c in COM:
    secs = P11[c['id']]
    tabs = row(*[chip(n, 'pressed' if i == 0 else '') for i, (n, _) in enumerate(secs)], gap=12, cls='wrap')
    rs = [mrow(n.rsplit(',', 1)[0], sample(n.rsplit(',', 1)[1].strip() if ',' in n else 'ед.', i), *chg_for(n.rsplit(',', 1)[1].strip() if ',' in n else 'ед.', i)) for i, n in enumerate(secs[0][1])]
    m = modal('остальные показатели', col(h3('разделы', 20), tabs, *rs, gap=10), 1254, scroll=len(rs) > 10)
    h = max(1080, 420 + len(rs) * 64 + 120)
    frame('p10', 'P-11.' + c['id'], 'Остальные показатели · ' + c['name'], f'Единый шаблон: вкладки разделов ({len(secs)}), до 20 строк на раздел, разные единицы. Показан первый раздел; остальные: ' + ', '.join(n for n, _ in secs[1:]) + '.', s08(c) + m, h=h)
for fid, eid, name, effects, note in P12:
    body = col(div('ill', f'иллюстрация события «{name}» (илл. 3.2.7) — событие показывается через последствия'), *[col(mrow(n, v, None), sm('длительность: ' + d, 13), gap=4) for n, v, d in effects],
               sm(note, 13) if note else '', btn('понятно', 'p'), gap=12)
    frame('p10', fid, name, f'{eid}. До 4 показателей с модификатором и длительностью (1, 2, 3 раунда или навсегда). Названия — по 1.7.', s08(U, event=name) + modal(name, body, 780))

