def resident(name, x, state):
    col_ = {'new': '#FD3286', 'pressed': '#F2F2F2', '': '#FD3286', 'choosen': 'transparent'}[state]
    fig = (f'<svg width="150" height="300" viewBox="0 0 15 30" shape-rendering="crispEdges"><g stroke="{col_}" stroke-width=".6">'
           f'<rect x="5" y="1" width="5" height="5" fill="#C9A27E"/><rect x="4" y="0" width="7" height="2" fill="#3B2A22"/>'
           f'<rect x="3" y="7" width="9" height="10" fill="{["#5B6E73", "#7B3F4A", "#3F5A6B", "#6B5B3F", "#4A3F6B"][x % 5]}"/>'
           f'<rect x="1" y="8" width="2" height="8" fill="#5B6E73"/><rect x="12" y="8" width="2" height="8" fill="#5B6E73"/>'
           f'<rect x="4" y="17" width="3" height="11" fill="#2C3436"/><rect x="8" y="17" width="3" height="11" fill="#2C3436"/></g></svg>')
    d = ''
    if state == 'pressed':
        d = f'<div class="dialog" style="left:{x - 75}px;top:330px"><span class="dlt">{e(name)}</span><span class="dlx">Лекции в арт-пространствах — огонь! Но на мой факультет мест опять не хватило.</span></div>'
    return f'{d}<div class="resid {state}" style="left:{x}px;top:500px">{fig}{badge(name, "pink", "s")}</div>'
