# ---------------- page ----------------
def build():
    font = base64.b64encode(open(os.path.join(HERE, 'pc.woff2'), 'rb').read()).decode()
    bg = 'data:image/jpeg;base64,' + base64.b64encode(open(os.path.join(HERE, 'bg.jpg'), 'rb').read()).decode()
    css = CSS.replace('__PCFONT__', font)
    # background via a single CSS variable to avoid repeating the data URI
    css = css.replace('url(__BG__)', 'var(--bgimg)')
    css = css.replace(':root{', ':root{--bgimg:url(' + bg + ');', 1)
    css += '.wrap-x{flex-wrap:wrap}.row.wrap{flex-wrap:wrap}.row.eq>*{flex:1 1 0;min-width:0}.self-start{align-self:flex-start}.slw .auto{align-self:flex-start}'
    nav = ''.join(f'<a href="#{k}">{e(t)}</a>' for k, t, _ in SECTIONS)
    secs = []
    total = 0
    for k, t, d in SECTIONS:
        cards = []
        for (s, fid, name, note, html_, h) in FRAMES:
            if s != k:
                continue
            total += 1
            tall = f' data-h="{h}"' if h != 1080 else ''
            cards.append(f'<article class="card" id="f-{e(fid).replace(".", "-")}"><div class="thumb" tabindex="0" role="button" aria-label="Открыть {e(fid)}"{tall}>{html_}</div>'
                         f'<div class="cap"><div class="idl"><span class="fid">{e(fid)}</span><span class="nm">{e(name)}</span></div><div class="nt">{e(note)}</div></div></article>')
        secs.append(f'<section class="sec" id="{k}"><h2>{e(t)}</h2><p>{e(d)}</p><div class="grid">{"".join(cards)}</div></section>')
    page = f'''<title>Симулятор мэра · экраны</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@500;600;700&display=swap">
<style>{css}</style>
<div class="page" lang="ru">
<header class="top"><h1>Симулятор мэра — экраны на согласование</h1>
<p>Все экраны, состояния и поп-апы по ТЗ: 1.1 User Flow, 1.4 ТЗ Дизайн и дополнение S-08, 1.5 Поведение интерфейса, 1.7 События, 1.8 Расширение города. Собраны по UI-киту «Коты – Мэр», шрифты — Pixel Code и Inter. Числа в макетах примерные.</p>
<p>Нажмите на макет, чтобы открыть его в полный размер. Замечания оставляйте комментарием и указывайте ID фрейма, например «S-08.trn: …».</p>
<div class="legend"><span><b>{total}</b> фреймов</span><span><b>S-xx</b> экран</span><span><b>P-xx</b> поп-ап</span><span><b>И-xx</b> поп-ап инструмента</span><span><b>.e</b> ошибка · <b>.h</b> организатор · <b>.a</b> альтернативное состояние</span></div>
</header>
<nav class="secs" aria-label="Разделы">{nav}</nav>
{"".join(secs)}
</div>
<div class="viewer" id="viewer" hidden><div class="vbar"><span class="fid" id="vid"></span><span class="nm" id="vnm"></span><span class="nt" id="vnt"></span>
<button type="button" id="vprev">← Предыдущий</button><button type="button" id="vnext">Следующий →</button><button type="button" id="vclose">Закрыть</button></div><div class="vstage" id="vstage"></div></div>
<script>
(function(){{
  var thumbs=[].slice.call(document.querySelectorAll('.thumb'));
  thumbs.forEach(function(t){{var f=t.firstElementChild;var need=1080;[].forEach.call(f.querySelectorAll('.modal'),function(m){{need=Math.max(need,m.offsetHeight+120);}});if(need>1080){{f.style.height=need+'px';t.dataset.h=need;}}}});
  function fit(t){{var f=t.firstElementChild;var k=t.clientWidth/1920;f.style.setProperty('--k',k);}}
  var ro=new ResizeObserver(function(es){{es.forEach(function(en){{fit(en.target);}});}});
  thumbs.forEach(function(t){{fit(t);ro.observe(t);}});
  var V=document.getElementById('viewer'),S=document.getElementById('vstage'),cur=-1,clone=null;
  function layout(){{if(!clone)return;var h=+(thumbs[cur].dataset.h||1080);var k=Math.min(S.clientWidth/1920,S.clientHeight/h);clone.style.transform='scale('+k+')';clone.style.left=((S.clientWidth-1920*k)/2)+'px';clone.style.top=Math.max(0,(S.clientHeight-h*k)/2)+'px';}}
  function open(i){{cur=(i+thumbs.length)%thumbs.length;var t=thumbs[cur];var card=t.closest('.card');S.innerHTML='';clone=t.firstElementChild.cloneNode(true);clone.style.removeProperty('--k');S.appendChild(clone);
    document.getElementById('vid').textContent=card.querySelector('.fid').textContent;document.getElementById('vnm').textContent=card.querySelector('.nm').textContent;document.getElementById('vnt').textContent=card.querySelector('.nt').textContent;
    V.hidden=false;layout();try{{history.replaceState(null,'','#'+card.id);}}catch(e){{}}}}
  function close(){{V.hidden=true;S.innerHTML='';clone=null;}}
  thumbs.forEach(function(t,i){{t.addEventListener('click',function(){{open(i);}});t.addEventListener('keydown',function(ev){{if(ev.key==='Enter'||ev.key===' '){{ev.preventDefault();open(i);}}}});}});
  document.getElementById('vclose').onclick=close;document.getElementById('vprev').onclick=function(){{open(cur-1);}};document.getElementById('vnext').onclick=function(){{open(cur+1);}};
  document.addEventListener('keydown',function(ev){{if(V.hidden)return;if(ev.key==='Escape')close();if(ev.key==='ArrowRight')open(cur+1);if(ev.key==='ArrowLeft')open(cur-1);}});
  window.addEventListener('resize',layout);
  var h=location.hash.slice(1);if(h&&h.indexOf('f-')===0){{var c=document.getElementById(h);if(c){{c.scrollIntoView();}}}}
}})();
</script>'''
    out = os.path.join(os.path.dirname(HERE), 'mayor-screens.html')
    open(out, 'w').write(page)
    print('frames', total, 'bytes', len(page.encode()))

build()
